const response = $input.first().json;
const lead = $('Eingabe validieren').first().json;

try {
  let content = response.choices?.[0]?.message?.content || '{}';
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const jsonMatch = content.match(/{[\s\S]*}/);
  const classification = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

  return [{
    json: {
      ...lead,
      classification: {
        score: classification.score || 5,
        kategorie: classification.kategorie || 'smb',
        hauptinteresse: classification.hauptinteresse || lead.message.substring(0, 100),
        dringlichkeit: classification.dringlichkeit || 'mittel',
        sprache: classification.sprache || 'de'
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      ...lead,
      classification: {
        score: 5,
        kategorie: 'smb',
        hauptinteresse: lead.message.substring(0, 100),
        dringlichkeit: 'mittel',
        sprache: 'de'
      }
    }
  }];
}

