const lead = $('Klassifikation parsen').first().json;
const response = $input.first().json;

const emailBody = response.choices?.[0]?.message?.content || '';

const isDE = lead.classification.sprache !== 'en';
const subject = isDE
  ? `Re: Ihre Anfrage — ${lead.classification.hauptinteresse.substring(0, 50)}`
  : `Re: Your inquiry — ${lead.classification.hauptinteresse.substring(0, 50)}`;

return [{
  json: {
    to: lead.email,
    subject,
    body: emailBody,
    lead_score: lead.classification.score,
    kategorie: lead.classification.kategorie,
    dringlichkeit: lead.classification.dringlichkeit,
    name: lead.name,
    company: lead.company,
    original_message: lead.message,
    received_at: lead.received_at
  }
}];
